  str_files_story_des_3204 = "เนื้อเรื่อง 4",
  str_files_story_des_3206 = "เนื้อเรื่อง 6",
  str_files_story_des_3301 = "ปุจฉา: คุณรู้จักเพื่อนเก่าที่ไปไหนด้วยกันกับคุณอยู่ทุกวันดีแค่ไหน คุณรู้จริง ๆ เหรอว่าในใจเธอคิดอะไรอยู่กันแน่ คำตอบของคำถามนี้คงลึกซึ้งน่าดู...",
  str_files_story_des_3303 = "ไหงแบบสำรวจของไวซ์มันฟังดูเหมือนบทสัมภาษณ์เลยละ คุณเริ่มประหม่าและหวังว่าไวซ์จะผ่อนปรนให้กับคุณนะ ไม่ว่าจะเรื่องอะไรก็ตามแต่...",
  str_files_story_des_3305 = "เนื้อเรื่อง 6",
  str_files_story_des_3307 = "เนื้อเรื่อง 8",
  str_files_story_des_3310 = "เนื้อเรื่อง 10",
  str_files_story_des_3501 = "ไม่นานมานี้เอโฮะส่งของไม่ตรงเวลาอีกแล้ว เพราะอะไรกัน ลองไปคุยกับเธอดูสิ...",
  str_files_story_des_3503 = "ตกลงแล้วเอโฮะนั้นมีความสามารถในการจดจำเส้นทางที่แย่มาก...คงทำงานลำบากไม่น้อยเลยสินะ...การทำสำเนาแผนที่ให้เธอจะช่วยให้เธอจำเส้นทางได้ง่ายขึ้นรึเปล่าหนอ...?",
  str_files_story_des_3505 = "เนื้อเรื่อง 5",
  str_files_story_des_3602 = "เนื้อเรื่อง 1",
  str_files_story_des_3604 = "เนื้อเรื่อง 3",
  str_files_story_des_3606 = "เนื้อเรื่อง 5",
  str_files_story_des_3608 = "เนื้อเรื่อง 7",
  str_files_story_des_3610 = "เนื้อเรื่อง 10",
  str_files_story_des_3802 = "ช่วงนี้คุณกรอนรูเป็นห่วงงานการบำรุงรักษายานโคลอสซัสเอามาก ๆ และดูจะกระตือรือร้นและสนใจเรื่องนี้เป็นพิเศษ วันนี้คือวันที่คุณทั้งคู่จะได้พบกันอย่างเป็นทางการ ชักอยากรู้แล้วสิว่าเธอเป็นคนแบบไหนกันนะ",
  str_files_story_des_3804 = "ดูเหมือนคุณกรอนรูจะชอบเล่นเกมและสนุกกับมันอย่างจริงจังเลยทีเดียว...หวังว่าการเล่นเกมจะไม่กระทบการงานประจำวันของเธอนะ ไม่งั้นคงลำบากน่าดู...",
  str_files_story_des_3806 = "เนื้อเรื่อง 6",
  str_files_story_des_3808 = "เนื้อเรื่อง 8",
  str_files_story_des_3809 = "เนื้อเรื่อง 9",
  str_files_story_des_3810 = "เนื้อเรื่อง 10",
  str_files_story_des_4001 = "เนื้อเรื่อง 1",
  str_files_story_des_4003 = "เนื้อเรื่อง 3",
  str_files_story_des_4005 = "เนื้อเรื่อง 5",
  str_files_story_des_4007 = "เนื้อเรื่อง 7",
  str_files_story_des_4101 = "มิสบลังค์มักยุ่งอยู่กับงานกิจกรรมใหญ่ ๆ เสมอ ลองไปหาเธอหน่อยไหม ถ้าได้ช่วยอะไรบ้างก็อาจจะดีกว่านี้ก็ได้ ถ้าไม่ทำตัวเกะกะนะ...",
  str_files_story_des_4103 = "อืมม... ดูท่าคุณจะยิ่งทำให้งานของมิสบลังค์ยุ่งยากขึ้นไปอีก และเธอก็ต้องยุ่งกว่าเดิมซะแล้ว... ลองหาวิธีชดเชยให้เธอหน่อยไหม",
  str_files_story_des_4105 = "เนื้อเรื่อง 5",
  str_files_story_des_4107 = "เนื้อเรื่อง 7",
  str_files_story_des_4402 = "เนื้อเรื่อง 2",
